set -e; cat > /app/cloudsql-v2/provider.py <<'PY'
from http.server import BaseHTTPRequestHandler,ThreadingHTTPServer
from pathlib import Path
import hashlib,json,socketserver,threading
R=Path('/app/cloudsql-v2')
def secret(name): return (R/name).read_text().strip()
state={'generation':'generation-one','status_identity':'enabled','connections':[]}
def bearer(h): return h.headers.get('Authorization','').removeprefix('Bearer ')
class API(BaseHTTPRequestHandler):
 def log_message(self,*a): pass
 def reply(self,code,body=b''):
  self.send_response(code); self.send_header('Content-Length',str(len(body))); self.end_headers()
  if self.command!='HEAD' and body: self.wfile.write(body)
 def admin(self): return bearer(self)==secret('sql-admin.token')
 def do_GET(self):
  if self.path=='/status': return self.reply(200,b'provider status\n') if state['status_identity']=='enabled' and bearer(self)==secret('provider-status.token') else self.reply(401)
  if self.path=='/admin/root' and self.admin():
   cert=R/'pki'/('root-g1.crt' if state['generation']=='generation-one' else 'root-g2.crt'); return self.reply(200,cert.read_bytes())
  self.reply(403)
 def do_HEAD(self):
  self.reply(204 if self.path=='/admin/instance' and self.admin() else 403)
 def do_POST(self):
  if not self.admin(): return self.reply(403)
  if self.path=='/admin/rotate': state['generation']='generation-two'; return self.reply(204)
  if self.path=='/admin/disable-status': state['status_identity']='disabled'; return self.reply(204)
  self.reply(404)
class DB(socketserver.StreamRequestHandler):
 def handle(self):
  line=self.rfile.readline().decode().strip().split(' ',2)
  if len(line)!=3 or line[0]!='AUTH': self.wfile.write(b'REJECTED\n'); return
  token,ident=line[1],line[2]
  if token not in (secret('orders-g1.password'),secret('orders-g2.password')): self.wfile.write(b'REJECTED\n'); return
  state['connections'].append(ident); self.wfile.write(b'CONNECTED role=orders-admin\n'); self.wfile.flush()
  while True:
   q=self.rfile.readline()
   if not q: break
   self.wfile.write(b'ROW orders=3\n'); self.wfile.flush()
class TCP(socketserver.ThreadingTCPServer): allow_reuse_address=True
api=ThreadingHTTPServer(('127.0.0.1',18443),API); db=TCP(('127.0.0.1',15432),DB)
threading.Thread(target=db.serve_forever,daemon=True).start(); api.serve_forever()
PY
