from pathlib import Path
import hashlib,sys,urllib.error,urllib.request
op,token_path=sys.argv[1:3]; token=Path(token_path).read_text().strip(); mapping={'root':('GET','/admin/root'),'rotate':('POST','/admin/rotate'),'instance':('HEAD','/admin/instance'),'status':('GET','/status'),'disable-status':('POST','/admin/disable-status')}; method,path=mapping[op]; req=urllib.request.Request('http://127.0.0.1:18443'+path,method=method,headers={'Authorization':'Bearer '+token})
try:
 with urllib.request.urlopen(req,timeout=5) as r: code=r.status; body=r.read()
except urllib.error.HTTPError as e: code=e.code; body=e.read()
if op=='root' and code==200:
 out=Path(sys.argv[3]); out.write_bytes(body); print('provider root_fetch http=200 sha256='+hashlib.sha256(body).hexdigest())
else: print(f'provider operation={op} http={code}')
